const runCommand = $((command: string) => {
  const chain = store.editor?.chain().focus();
  if (!chain) return;
  switch (command) {
    case "bold":
      chain.toggleBold().run();
      break;
    case "italic":
      chain.toggleItalic().run();
      break;
    case "underline":
      chain.toggleUnderline().run();
      break;
    case "strike":
      chain.toggleStrike().run();
      break;
    case "highlight":
      chain.toggleHighlight().run();
      break;
    case "h1":
      chain.toggleHeading({ level: 1 }).run();
      break;
    case "h2":
      chain.toggleHeading({ level: 2 }).run();
      break;
    case "h3":
      chain.toggleHeading({ level: 3 }).run();
      break;
    case "bullet":
      chain.toggleBulletList().run();
      break;
    case "ordered":
      chain.toggleOrderedList().run();
      break;
    case "taskList":
      chain.toggleTaskList().run();
      break;
    case "blockquote":
      chain.toggleBlockquote().run();
      break;
    case "code":
      chain.toggleCodeBlock().run();
      break;
    case "left":
      chain.setTextAlign("left").run();
      break;
    case "center":
      chain.setTextAlign("center").run();
      break;
    case "right":
      chain.setTextAlign("right").run();
      break;
    case "horizontal":
      chain.setHorizontalRule().run();
      break;
    case "undo":
      chain.undo().run();
      break;
    case "redo":
      chain.redo().run();
      break;
    case "insertTable":
      chain.insertTable({ rows: 3, cols: 3, withHeaderRow: true }).run();
      store.showTableTools = true;
      break;
    case "addRowBefore":
      chain.addRowBefore().run();
      break;
    case "addRowAfter":
      chain.addRowAfter().run();
      break;
    case "deleteRow":
      chain.deleteRow().run();
      break;
    case "addColumnBefore":
      chain.addColumnBefore().run();
      break;
    case "addColumnAfter":
      chain.addColumnAfter().run();
      break;
    case "deleteColumn":
      chain.deleteColumn().run();
      break;
    case "toggleHeaderRow":
      chain.toggleHeaderRow().run();
      break;
    case "toggleHeaderColumn":
      chain.toggleHeaderColumn().run();
      break;
    case "mergeCells":
      chain.mergeCells().run();
      break;
    case "splitCell":
      chain.splitCell().run();
      break;
    case "deleteTable":
      chain.deleteTable().run();
      store.showTableTools = false;
      break;
    case "addComment": {
      const editor = store.editor!;
      const { from, to } = editor.state.selection;
      if (from === to) break;
      const commentId = crypto.randomUUID();
      const body = store.commentText.trim() || "New comment";
      const anchor = editor.state.doc.textBetween(from, to);
      const folioId = store.activeFolioId || "";
      chain
        .setMark("commentMark", {
          commentId,
          author: "You",
          color: "var(--color-mustard)",
        })
        .run();

      // Persist the body locally + push to Convex. Fire-and-forget
      // so the sync doesn't block the mark from being set.
      void persistNewComment(commentId, body, anchor, folioId);

      // Open the popover immediately so the writer can keep typing
      // replies or strike the note.
      const sel = window.getSelection();
      const markEl = sel?.anchorNode?.parentElement?.closest(
        ".twyne-comment-mark",
      ) as HTMLElement | null;
      if (markEl) {
        void openUserCommentPopover(commentId, markEl);
      }

      store.commentText = "";
      store.showCommentInput = false;
      break;
    }
    case "insertMermaid": {
      if (store.mermaidSource.trim()) {
        chain
          .setMermaidDiagram({ source: store.mermaidSource.trim() })
          .run();
        store.mermaidSource = "";
        store.showMermaidInput = false;
      }
      break;
    }
  }
});

