import { Node, mergeAttributes } from "@tiptap/core";

export interface EndnoteNodeOptions {
  HTMLAttributes: Record<string, any>;
}

export interface EndnoteNodeAttributes {
  text: string;
}

declare module "@tiptap/core" {
  interface Commands<ReturnType> {
    endnoteNode: {
      setEndnote: (attrs: EndnoteNodeAttributes) => ReturnType;
    };
  }
}

export const EndnoteNode = Node.create<EndnoteNodeOptions>({
  name: "endnote",

  group: "inline",

  inline: true,

  atom: true,

  selectable: true,

  addOptions() {
    return {
      HTMLAttributes: {},
    };
  },

  addAttributes() {
    return {
      text: {
        default: "",
        parseHTML: (element) =>
          element.getAttribute("data-endnote-text") ?? "",
        renderHTML: (attributes) => {
          if (!attributes.text) return {};
          return { "data-endnote-text": attributes.text };
        },
      },
    };
  },

  parseHTML() {
    return [
      {
        tag: 'sup[data-type="endnote"]',
      },
    ];
  },

  renderHTML({ HTMLAttributes }) {
    return [
      "sup",
      mergeAttributes(this.options.HTMLAttributes, HTMLAttributes, {
        "data-type": "endnote",
        class: "twyne-endnote",
      }),
    ];
  },

  addCommands() {
    return {
      setEndnote:
        (attrs) =>
        ({ chain }) => {
          return chain()
            .insertContent({
              type: this.name,
              attrs: { text: attrs.text },
            })
            .run();
        },
    };
  },
});

