file.content:
  font-family: var(--font-serif);
  font-style: italic;
  font-size: 0.95rem;
  line-height: 1.65;
  color: var(--color-ink-light);
}

/* ─────────────────────────────────────────────────────────────
 * Micro-interactions — editorial paper metaphors
 *   .ink-bleed       : hover effect that simulates ink spreading
 *   .page-turn       : card hover with a subtle page-lift shadow
 *   .type-cursor     : blinking typewriter caret
 *   .slide-in        : content slides in from below on mount
 *   .fade-in         : simple opacity fade-in on mount
 *   .citation-card   : detected-citation card hover (used by panels)
 * ───────────────────────────────────────────────────────────── */

@keyframes ink-bleed {
  0% {
    text-shadow: 0 0 0 transparent;
  }
  100% {
    text-shadow: 0.5px 0.5px 0px color-mix(in srgb, var(--color-ink) 12%, transparent);
  }
}

@keyframes slide-in-below {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

@keyframes fade-in {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes type-blink {
  0%, 49% { opacity: 1; }
  50%, 100% { opacity: 0; }
}

.slide-in {
  animation: slide-in-below 0.25s cubic-bezier(0.22, 1, 0.36, 1) both;
}

.fade-in {
  animation: fade-in 0.2s ease-out both;
}

/* Page-lift hover on cards — simulates lifting a page from a stack */
.page-turn {
  transition:
    transform 0.18s cubic-bezier(0.22, 1, 0.36, 1),
    box-shadow 0.18s ease,
    border-color 0.18s ease;
}
.page-turn:hover {
  transform: translateY(-2px);
  box-shadow:
    0 1px 0 rgba(255, 255, 255, 0.7) inset,
    0 8px 20px -12px rgba(31, 27, 22, 0.35);
}
.page-turn:active {
  transform: translateY(0px);
  box-shadow: 0 2px 8px -6px rgba(31, 27, 22, 0.2);
}

/* Blinking typewriter caret */
.type-cursor::after {
  content: "\25ae";
  display: inline-block;
  margin-left: 1px;
  font-size: 0.75em;
  color: var(--color-vermilion);
  animation: type-blink 1.1s step-end infinite;
}

/* Endnote markers in the editor */
.twyne-endnote {
  font-size: 0.7em;
  vertical-align: super;
  line-height: 0;
  color: var(--color-vermilion);
  cursor: pointer;
  font-family: var(--font-typewriter);
  font-weight: 600;
  transition: color 0.15s ease, background 0.15s ease;
  padding: 0 0.1em;
  border-radius: 1px;
}
.twyne-endnote:hover {
  color: var(--color-vermilion-2);
  background: color-mix(in srgb, var(--color-vermilion) 10%, transparent);
}

/* Ink-bleed text effect for headings on hover */
.ink-bleed {
  transition: text-shadow 0.3s ease;
}
.ink-bleed:hover {
  animation: ink-bleed 0.3s ease forwards;
}

/* Department label — subtle underline grow on hover */
.dept-label {
  transition: letter-spacing 0.2s ease;
}
.dept-label:hover {
  letter-spacing: 0.22em;
}

/* Icon button — press-down feedback */
.icon-btn {
  transition: transform 0.1s ease, color 0.15s ease;
}
.icon-btn:active {
  transform: scale(0.92);
}

/* Smooth color transitions on interactive text */
button, a {
  transition: color 0.15s ease, background 0.15s ease, border-color 0.15s ease;
}

/* Zen masthead — collapses the header to a thin bar, fading out all
   chrome except the zen toggle. Fades back in on hover. */
.zen-masthead {
  transition: max-height 0.3s ease, opacity 0.3s ease;
  max-height: 0;
  opacity: 0;
  overflow: hidden;
  border-bottom: none !important;
  pointer-events: none;
}
.zen-masthead:hover {
  max-height: 80px;
  opacity: 1;
  pointer-events: auto;
  border-bottom: 2px double var(--color-paper-3) !important;
}

/* Toast / status pulse — gentle attention without being aggressive */
@keyframes gentle-pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.6; }
}
.gentle-pulse {
  animation: gentle-pulse 2s ease-in-out infinite;
}

/* Reduced motion: disable all micro-interactions */
@media (prefers-reduced-motion: reduce) {
  .slide-in,
  .fade-in,
  .page-turn,
  .ink-bleed,
  .type-cursor::after,
  .gentle-pulse {
    animation: none !important;
    transition: none !important;
    transform: none !important;
  }
  .zen-masthead {
    transition: none !important;
  }
}

/* ── Comment Markdown ──────────────────────────────────────── */
/* Lightweight prose styling for the short Markdown rendered in
   margin comments, persona notes, and suggestion rationales.
   Scoped via `.comment-markdown` so it never bleeds into the
   editor's prose or manuscript paste. */
.comment-markdown {
  /* Honor the host's line-height / colour set inline; only add
     the bits Markdown needs. */
}

.comment-markdown p {
  margin: 0;
  /* marked emits one paragraph per blank-line block. Soft breaks
     inside a paragraph are <br>, which contributes its own space;
     trim the trailing gap so multiple paragraphs don't double up
     when the host uses `space-y-*` layout. */
}
.comment-markdown p + p {
  margin-top: 0.45em;
}

.comment-markdown ul,
.comment-markdown ol {
  margin: 0.4em 0;
  padding-left: 1.25em;
  list-style-position: outside;
}
.comment-markdown ul { list-style-type: disc; }
.comment-markdown ol { list-style-type: decimal; }
.comment-markdown li {
  margin: 0.15em 0;
}
.comment-markdown li > p {
  display: inline;
  margin: 0;
}

.comment-markdown strong {
  font-weight: 600;
  color: var(--color-ink);
}
.comment-markdown em {
  font-style: italic;
}
.comment-markdown code {
  font-family: var(--font-typewriter);
  font-size: 0.92em;
  padding: 0 0.25em;
  border-radius: 1px;
  background: var(--color-paper-3);
  color: var(--color-ink);
}
.comment-markdown a {
  color: var(--color-cobalt);
  text-decoration: underline;
  text-decoration-thickness: 1px;
  text-underline-offset: 2px;
}
.comment-markdown a:hover {
  color: var(--color-vermilion);
}

/* When a persona-coloured bubble renders Markdown on its coloured
   background, the default cobalt link and paper-3 code chip clash.
   Override against the persona color by switching the code chip to a
   translucent ink and letting links pick up the inverse highlight. */
.comment-markdown-on-color code {
  background: rgba(244, 236, 216, 0.18);
  color: var(--color-paper);
}
.comment-markdown-on-color a {
  color: var(--color-paper);
  text-decoration-color: rgba(244, 236, 216, 0.6);
}

