168	/** Regex to find endnote nodes in the editor HTML. */
169	const ENDNODE_RE =
170	  /<sup[^>]*data-type="endnote"[^>]*data-endnote-text="([^"]*)"[^>]*>\s*(?:<[^>]*>\s*)*<\/sup>/gi;
171	
172	/**
173	 * Extract endnote texts from inline `<sup data-type="endnote">` nodes
174	 * in the editor HTML, returning the texts in document order.
175	 */
176	export function extractEndnotes(html: string): string[] {
177	  const notes: string[] = [];
178	  let m: RegExpExecArray | null;
179	  ENDNODE_RE.lastIndex = 0;
180	  while ((m = ENDNODE_RE.exec(html)) !== null) {
181	    notes.push(htmlDecode(m[1]));
182	  }
183	  return notes;
184	}
185	
186	/**
187	 * Replace endnote `<sup>` nodes in the HTML with numbered superscript
188	 * references (¹ ² ³ …) so the exported body reads naturally.
189	 */
190	function replaceEndnotesWithSuperscripts(html: string): string {
191	  let i = 0;
192	  return html.replace(ENDNODE_RE, () => {
193	    i++;
194	    return `<sup class="endnote-ref">${toSuperscript(i)}</sup>`;
195	  });
196	}
197	
198	/** Convert a number to Unicode superscript digits. */
199	function toSuperscript(n: number): string {
200	  const map: Record<string, string> = {
201	    "0": "\u2070",
202	    "1": "\u00b9",
203	    "2": "\u00b2",
204	    "3": "\u00b3",
205	    "4": "\u2074",
206	    "5": "\u2075",
207	    "6": "\u2076",
208	    "7": "\u2077",
209	    "8": "\u2078",
210	    "9": "\u2079",
211	  };
212	  return String(n)
213	    .split("")
214	    .map((d) => map[d] ?? d)
215	    .join("");
