219	 * Strip editor-only marks (persona notes, suggestions, comments) from
220	 * the HTML so the exported manuscript is clean prose. Endnote `<sup>`
221	 * nodes are preserved — they are handled separately.
222	 */
223	function stripEditorMarks(html: string): string {
224	  return html
225	    // Remove persona-note spans but keep the text inside.
226	    .replace(
227	      /<span[^>]*class="twyne-persona-note"[^>]*>([\s\S]*?)<\/span>/gi,
228	      "$1",
229	    )
230	    // Remove suggestion spans — keep the original text (not the replacement).
231	    .replace(
232	      /<span[^>]*class="twyne-suggestion"[^>]*>([\s\S]*?)<\/span>/gi,
233	      "$1",
234	    )
235	    // Remove comment marks but keep text.
236	    .replace(
237	      /<span[^>]*class="twyne-comment-mark"[^>]*>([\s\S]*?)<\/span>/gi,
238	      "$1",
239	    );
240	}
