242	/** Build the endnotes section HTML from marginalia + inline endnotes. */
243	function buildEndnotesSection(
244	  inlineNotes: string[],
245	  marginalia: PersonaFeedback[],
246	): string {
247	  const entries: Array<{ source: string; text: string }> = [];
248	
249	  for (const text of inlineNotes) {
250	    entries.push({ source: "note", text });
251	  }
252	
253	  for (const m of marginalia) {
254	    const author = m.personaName || "Editor";
255	    const quote = m.anchor ? `"${m.anchor}" — ` : "";
256	    entries.push({
257	      source: author,
258	      text: `${quote}${m.feedback}`,
259	    });
260	  }
261	
262	  if (entries.length === 0) return "";
263	
264	  const items = entries
265	    .map(
266	      (e, i) =>
267	        `<li id="endnote-${i + 1}"><sup>${toSuperscript(i + 1)}</sup> ` +
268	        `<span class="endnote-source">${escapeHtml(e.source)}</span>: ` +
269	        `${escapeHtml(e.text)}</li>`,
270	    )
271	    .join("\n");
