338	    parts.push(`- **Tone:** ${p.brief.answers.tone}`);
339	    parts.push(`- **Constraints:** ${p.brief.answers.constraints}`);
340	    parts.push(`- **Success signal:** ${p.brief.answers.successSignal}`);
341	    parts.push("");
342	    parts.push("---");
343	    parts.push("");
344	  }
345	  parts.push(htmlToMarkdown(body));
346	  parts.push("");
347	
348	  // Endnotes (inline + marginalia)
349	  const endEntries: Array<{ source: string; text: string }> = [];
350	  for (const text of inlineNotes) {
351	    endEntries.push({ source: "note", text });
352	  }
353	  for (const m of p.marginalia ?? []) {
354	    const author = m.personaName || "Editor";
355	    const quote = m.anchor ? `"${m.anchor}" — ` : "";
356	    endEntries.push({ source: author, text: `${quote}${m.feedback}` });
357	  }
358	  if (endEntries.length > 0) {
359	    parts.push("---");
360	    parts.push("");
361	    parts.push("## Notes");
362	    parts.push("");
363	    endEntries.forEach((e, i) => {
364	      parts.push(`${i + 1}. **${e.source}**: ${e.text}`);
365	    });
366	    parts.push("");
367	  }
368	
369	  // Footnotes (bibliography)
370	  const bibEntries = (p.bibliography ?? []).filter(
371	    (b) => b.url || b.doi || b.title,
372	  );
373	  if (bibEntries.length > 0) {
374	    if (endEntries.length === 0) {
375	      parts.push("---");
376	      parts.push("");
377	    }
378	    parts.push("## Footnotes");
379	    parts.push("");
380	    bibEntries.forEach((e, i) => {
381	      parts.push(`${i + 1}. ${formatCitation(e, style)}`);
382	    });
383	    parts.push("");
384	  }
385	
386	  return parts.join("\n");
387	}
