/** Regex to find endnote nodes in the editor HTML. */
const ENDNODE_RE =
  /<sup[^>]*data-type="endnote"[^>]*data-endnote-text="([^"]*)"[^>]*>\s*(?:<[^>]*>\s*)*<\/sup>/gi;

/**
 * Extract endnote texts from inline `<sup data-type="endnote">` nodes
 * in the editor HTML, returning the texts in document order.
 */
export function extractEndnotes(html: string): string[] {
  const notes: string[] = [];
  let m: RegExpExecArray | null;
  ENDNODE_RE.lastIndex = 0;
  while ((m = ENDNODE_RE.exec(html)) !== null) {
    notes.push(htmlDecode(m[1]));
  }
  return notes;
}

/**
 * Replace endnote `<sup>` nodes in the HTML with numbered superscript
 * references (¹ ² ³ …) so the exported body reads naturally.
 */
function replaceEndnotesWithSuperscripts(html: string): string {
  let i = 0;
  return html.replace(ENDNODE_RE, () => {
    i++;
    return `<sup class="endnote-ref">${toSuperscript(i)}</sup>`;
  });
}

