function buildFootnotesSection(
  bibliography: BibEntry[],
  style: CitationStyle,
): string {
  const entries = bibliography.filter((b) => b.url || b.doi || b.title);
  if (entries.length === 0) return "";

  const items = entries
    .map((e, i) => {
      const cite = footnoteCite(e, style);
      const full = formatCitation(e, style);
      return `<li id="footnote-${i + 1}"><sup>${toSuperscript(i + 1)}</sup> ${escapeHtml(full)}</li>`;
    })
    .join("\n");

  return `<section class="footnotes">\n<h2>Footnotes</h2>\n<ol>\n${items}\n</ol>\n</section>\n`;
}

